// Exploratory rules; no psychometric or employment prediction claim.
const labExperts=[['진로상담','흥미와 실력을 구분하고 재탐색 허용'],['고교 진학상담','대학 합격 예측 없이 교육과정 확인'],['교육심리','점수 비교 대신 경험과 자기 설명'],['청소년 상담','불안·미결정 상태에서도 건너뛰기'],['학습코칭','작은 체험과 기초학업 병행'],['교육과정','학과명보다 배우는 내용 확인'],['AI 연구','시연과 현장 확산 구분'],['미래학','10·20·30년은 조건부 시나리오'],['노동경제','직업과 직업 안의 업무 변화 구분'],['채용·인사','취업 보장·수요 순위 사용 안 함'],['컴퓨터공학','코딩 도구와 원리·검증 함께 학습'],['전자·로봇공학','하드웨어·소프트웨어·현장 모두 안내'],['기계·제조','실습 안전과 장비 업무 부담 확인'],['보안','허가된 환경과 개인정보 보호'],['바이오·보건','면허·자격 경로 별도 확인'],['환경·에너지','기술·비용·정책 함께 검토'],['디자인·UX','제작보다 사용자 문제·피드백 강조'],['경영·제품','고객·비용·데이터 연결'],['교육·복지','관계·돌봄의 정서 부담 안내'],['도시·물류','설계·현장·운영 역할 구분'],['직업교육','전문대·직업교육 경로도 검토'],['접근성','키보드·복수선택·모바일 버튼'],['추천시스템','추천 규칙과 동점 처리 공개'],['정보윤리','관심·기록은 이 기기에만 저장']];
const labUsers=[['기기 좋아하는 고1','휴대폰만 좋아해도 시작 가능한가','기기 분야와 디자인·제품 분야를 함께 제시'],['문과 성향 고1','수학을 안 골라도 막히지 않는가','국어·사회·영어·사람 이해로 탐색 허용'],['진로 미결정 고1','아무것도 고르지 않아도 가능한가','빈 선택이면 10개 분야를 같은 순서로 표시'],['과학 탐구형 고2','연구와 실제 업무가 연결되는가','전공·공부·체험·업무를 함께 표시'],['미술·콘텐츠형 고1','비공학 직업도 보이는가','디자인·미디어·UX 분야 유지'],['사람 돕기형 고2','돌봄과 면허를 구분하는가','교육·복지·보건 자격 확인 안내'],['현장 실습형 고2','4년제만 권하지 않는가','전문대·직업교육 비교 안내'],['진학 고민 고3','결과를 합격 확률로 오해하는가','일치 점수·합격률 대신 연결 이유 표시'],['여러 관심 고1','두 분야를 비교할 수 있는가','최대 2개 후보 나란히 비교'],['휴대폰·작은 화면 사용자','긴 결과를 읽고 다시 선택 가능한가','4단계·접기·재탐색·큰 버튼 적용']];
const labStyles=['문서·데이터 중심','사람과 대화하기','만들고 실험하기','현장·장비 다루기','아직 모르겠어요'];
const labStyleNotes={'문서·데이터 중심':'분석·기획도 회의와 설명이 필요해요. 현장 비중이 낮은 역할인지 채용 공고·직무 인터뷰에서 확인해 보세요.','사람과 대화하기':'교육·상담·제품·영업 등에서 소통을 연습해요. 감정 노동과 자격 요건도 확인하세요.','만들고 실험하기':'소프트웨어·디자인·공학·바이오 등에서 제작하고 검증해요. 필요한 수학·실습 부담을 작은 체험으로 확인하세요.','현장·장비 다루기':'제조·자동화·인프라·농업 등에서 장비·안전·실습이 중요해요. 근무 장소와 업무 강도를 함께 확인하세요.'};
let labStep=0;const labTopics=new Set(),labCompare=new Set(),labWork=new Set();let labReflection={};
try{const v=JSON.parse(localStorage.getItem('compass-career-lab')||'{}');for(const id of v.topics||[])if(domains.some(d=>d.id===id))labTopics.add(id);for(const id of v.compare||[])if(domains.some(d=>d.id===id)&&labCompare.size<2)labCompare.add(id);for(const w of v.work||[])if(labStyles.includes(w))labWork.add(w);if(v.reflection&&typeof v.reflection==='object'&&!Array.isArray(v.reflection))labReflection=v.reflection}catch{}
const labEsc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function labSave(){try{localStorage.setItem('compass-career-lab',JSON.stringify({topics:[...labTopics],compare:[...labCompare],work:[...labWork],reflection:labReflection}));saveProgress()}catch{}}
function labRank(){return domains.map((d,i)=>({d,i,score:(labTopics.has(d.id)?3:0)+d.activities.filter(x=>chosenActivities.has(x)).length*2+d.subjects.filter(x=>chosenSubjects.has(x)).length})).sort((a,b)=>b.score-a.score||a.i-b.i)}
function labReason(d){const r=[];if(labTopics.has(d.id))r.push('관심 주제로 직접 선택했어요');const s=d.subjects.filter(x=>chosenSubjects.has(x)),a=d.activities.filter(x=>chosenActivities.has(x));if(s.length)r.push('연결 과목: '+s.join(' · '));if(a.length)r.push('연결 활동: '+a.join(' · '));return r.length?r.join('<br>'):'선택과 직접 겹치지 않아도 새로운 관심이 될 수 있어요.'}
function labPick(items,set,key){return `<div class="lab-picks">${items.map(x=>`<button data-lab-${key}="${labEsc(x)}" aria-pressed="${set.has(x)}" class="${set.has(x)?'selected':''}">${labEsc(x)}</button>`).join('')}</div>`}
function labReview(){return `<details class="lab-review"><summary>기획·감수 기준: 전문가 24관점 · 고등학생 10유형</summary><p>실제 전문가·학생을 섭외한 자문이나 사용성 실험이 아닙니다. 가상 관점으로 기획을 교차 검토하고, 아래 10유형의 입력·결과는 자동화 시나리오로 점검했습니다. 실제 학생 사용 후에는 별도 인터뷰와 관찰이 필요합니다.</p><h3>전문가 검토 관점</h3><div class="grid">${labExperts.map(([a,b],i)=>`<div><strong>${i+1}. ${a}</strong><p>${b}</p></div>`).join('')}</div><h3>고등학생 사용 시나리오와 반영</h3>${labUsers.map(([a,b,c],i)=>`<p><strong>${i+1}. ${a}</strong><br>검토 질문: ${b}<br>반영: ${c}</p>`).join('')}<h3>정보 확인</h3><p><a href="https://www.career.go.kr/cloud/" target="_blank" rel="noopener">커리어넷: 직업·학과·흥미검사 확인</a><br><a href="https://www.weforum.org/publications/the-future-of-jobs-report-2025/digest/" target="_blank" rel="noopener">WEF 2025: 기업들의 2030년 업무·역량 전망</a></p><p>2026-10-04 확인. 본 도구의 연결 규칙은 자체 기획이며 공식 검사나 WEF 추천 알고리즘이 아닙니다. 대학 선택과목·전형·자격은 해당 기관의 최신 안내를 확인하세요.</p></details>`}
const legacyExplore=exploring;
exploring=function(){if(route==='flow')return legacyExplore()+labReview();const labels=['관심 주제','과목·활동','일하는 방식','비교·체험'];let body='';
if(labStep===0)body=`<h2>궁금한 미래를 골라볼까?</h2><p>여러 개 골라도 되고, 아직 모르겠다면 다음으로 넘어가도 돼.</p><div class="lab-topic-grid">${domains.map(d=>`<button data-lab-topic="${d.id}" class="${labTopics.has(d.id)?'selected':''}" aria-pressed="${labTopics.has(d.id)}"><span>${personalEmojis[d.id]||'✨'}</span><strong>${d.name}</strong><small>${d.life}</small></button>`).join('')}</div>`;
if(labStep===1)body=`<h2>좋아하는 과목과 해보고 싶은 활동</h2><p>성적과 별개로 골라봐. 잘 모르겠으면 건너뛰어도 괜찮아.</p><h3>과목</h3>${labPick(subjectOptions,chosenSubjects,'subject')}<h3>활동</h3>${labPick(activityOptions,chosenActivities,'activity')}`;
if(labStep===2)body=`<h2>어떤 방식으로 일하고 싶어?</h2><p>지금 생각을 골라봐. 추천 순위에는 반영하지 않고, 업무 환경을 확인할 때 참고해.</p>${labPick(labStyles,labWork,'work')}${[...labWork].filter(w=>labStyleNotes[w]).map(w=>`<div class="note"><strong>${w}</strong><br>${labStyleNotes[w]}</div>`).join('')}`;
if(labStep===3){const ranked=labRank(),has=labTopics.size+chosenSubjects.size+chosenActivities.size;body=`<h2>${has?'먼저 체험해 볼 후보':'아직 몰라도, 한 분야부터 구경해 보자'}</h2><p>탐색 순서일 뿐 적성·성공·합격 확률은 아니야. 두 분야를 골라 비교하고 작은 체험을 해봐.</p><details><summary>추천 순서가 정해지는 방법</summary><p>직접 고른 주제 3점 + 겹치는 활동 각각 2점 + 겹치는 과목 각각 1점. 점수는 탐색을 정렬하는 자체 규칙이고 검증된 검사 점수가 아닙니다. 동점은 기존 분야 순서입니다. 선택이 없으면 모든 분야를 기존 순서로 보여줍니다. 일하는 방식은 순위에서 제외합니다.</p></details><div class="grid">${ranked.map(({d},i)=>`<article class="card"><span class="tag">${has?i+1+'번째 탐색 후보':'자유 탐색'}</span><h3>${d.name}</h3><p>${labReason(d)}</p><p><strong>직업 예시</strong><br>${d.jobs.join(' · ')}</p><button data-domain="${d.id}" class="jobbutton">업무·학과·공부 자세히</button> <button data-lab-compare="${d.id}" class="jobbutton" aria-pressed="${labCompare.has(d.id)}">${labCompare.has(d.id)?'비교에서 빼기':'비교에 담기'}</button></article>`).join('')}</div>${activeDomain?domainDetails(domains.find(d=>d.id===activeDomain)||domains[0]):''}<section class="section"><h2>두 후보 비교 · ${labCompare.size}/2</h2><p id="lab-status" role="status">최대 두 분야를 담아 비교해요.</p><div class="grid">${[...labCompare].map(id=>{const d=domains.find(d=>d.id===id);return `<article class="card"><h3>${d.name}</h3><p><strong>실제 업무</strong><br>${d.work}</p><p><strong>학과 · 과목</strong><br>${d.majors}<br>${d.subjects.join(' · ')}</p><p><strong>공부 순서</strong><br>① 학교 기초 과목 보완<br>② ${d.prep}<br>③ 작은 결과물을 만들고 원리·실패 설명하기</p><p><strong>이번 주 체험</strong><br>${d.task}</p><p><strong>10·20·30년 준비</strong><br>10년: 기초·실무 경험 → 20년: 여러 시스템·사람을 연결 → 30년: 새 도구·역할을 다시 학습. 시점은 성장 계획의 예시입니다.</p><p><strong>계속 확인할 점</strong><br>${d.risk}</p><label for="reflection-${id}"><strong>체험 후 기록</strong><br>재미있던 점 · 어려웠던 점 · 다시 해볼 것</label><textarea id="reflection-${id}" data-lab-reflection="${id}" maxlength="600" rows="4" placeholder="아직 체험 전이라면 해보고 싶은 질문부터 적어봐.">${labEsc(labReflection[id]||'')}</textarea></article>`}).join('')}</div>${labCompare.size?'':'<div class="callout">위에서 ‘비교에 담기’를 눌러봐. 다른 두 분야를 골라도 괜찮아.</div>'}</section><section class="card section"><h2>이번 주 30분 실천</h2><p>10분: 업무·학과 읽기 → 10분: 체험 질문 정하기 → 10분: 관찰·자료 조사 후 기록. 제작·실험은 별도 시간을 잡고 안전한 범위에서 해봐.</p><button class="jobbutton" data-page="plan">12주 준비계획 연결</button><p>전문대·직업교육·4년제 모두 교육과정·실습·비용·자격을 비교해요. 추천 목록에 없다고 나에게 안 맞는 분야는 아닙니다.</p></section>`}
return `<div class="tabs"><button data-route="flow">미래 변화에서 찾기</button><button data-route="self" class="active">나에게서 찾기</button></div><nav class="lab-steps" aria-label="진로 탐색 단계">${labels.map((l,i)=>`<button data-lab-step="${i}" ${labStep===i?'aria-current="step"':''}>${i+1}. ${l}</button>`).join('')}</nav><section class="lab-surface">${body}<div class="lab-controls">${labStep>0?`<button data-lab-step="${labStep-1}">이전</button>`:''}${labStep<3?`<button class="primary" data-lab-step="${labStep+1}">${labStep===2?'후보 보기':'다음 · 몰라도 괜찮아'}</button>`:'<button data-lab-step="0">관심 다시 고르기</button>'}</div></section><p class="mini">선택·체험 기록은 이 브라우저에만 저장돼요. 이름·성적을 입력할 필요 없어요. 공용 기기에서는 ‘내 탐색 기록 지우기’를 눌러요.</p><button class="text-button" data-lab-reset>내 탐색 기록 지우기</button>${labReview()}`};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;let changed=false;for(const [key,set,valid]of [['topic',labTopics,domains.map(d=>d.id)],['subject',chosenSubjects,subjectOptions],['activity',chosenActivities,activityOptions],['work',labWork,labStyles]]){const v=b.dataset['lab'+key[0].toUpperCase()+key.slice(1)];if(v&&valid.includes(v)){set.has(v)?set.delete(v):set.add(v);changed=true}}
if(b.dataset.labStep!==undefined){labStep=Math.max(0,Math.min(3,Number(b.dataset.labStep)||0));changed=true}if(b.dataset.labCompare){const id=b.dataset.labCompare;if(domains.some(d=>d.id===id)){if(labCompare.has(id))labCompare.delete(id);else if(labCompare.size<2)labCompare.add(id);else{const s=document.querySelector('#lab-status');if(s)s.textContent='먼저 한 후보를 빼면 다른 분야를 담을 수 있어요.';return}changed=true}}
if(b.hasAttribute('data-lab-reset')){labTopics.clear();labWork.clear();labCompare.clear();chosenSubjects.clear();chosenActivities.clear();labReflection={};labStep=0;activeDomain=null;changed=true}if(changed){labSave();render();} });
document.addEventListener('input',e=>{const id=e.target.dataset?.labReflection;if(id&&domains.some(d=>d.id===id)){labReflection[id]=e.target.value.slice(0,600);labSave()}});

titles.explore=['CAREER LAB','승준이의 진로탐색기','관심을 고르고, 두 분야를 비교하고, 작은 체험으로 확인해 보자.'];
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.page==='explore'){route='self';render()}});
if(location.hash==='#career-lab'){page='explore';route='self';render()}
